#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_OUT 1024

static char main_out[MAX_OUT];

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];
    size_t out_len = 0;

    if (strcmp(mode, "to_camel") == 0) {
        int capitalize = 0;
        for (size_t i = 0; input[i] && out_len < MAX_OUT - 1; ++i) {
            char c = input[i];
            if (c == '_') {
                capitalize = 1;
                continue; // skip underscore
            }
            if (capitalize) {
                c = (char)toupper((unsigned char)c);
                capitalize = 0;
            }
            main_out[out_len++] = c;
        }
    } else if (strcmp(mode, "to_snake") == 0) {
        int first = 1; // first character flag
        for (size_t i = 0; input[i] && out_len < MAX_OUT - 1; ++i) {
            char c = input[i];
            if (isupper((unsigned char)c)) {
                if (!first) {
                    main_out[out_len++] = '_';
                }
                c = (char)tolower((unsigned char)c);
            }
            main_out[out_len++] = c;
            first = 0;
        }
    } else {
        puts("INVALID_MODE");
        return 0;
    }
    main_out[out_len] = '\0';
    puts(main_out);
    return 0;
}
